-- AcademicVault Phase 6: Internships, Courses, Skills
create extension if not exists pgcrypto;
create table if not exists public.internships (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, academic_year_id uuid references public.academic_years(id) on delete set null, semester_id uuid references public.semesters(id) on delete set null, company text not null, role text, start_date date, end_date date, internship_type text not null default 'internship', location text, description text, technologies text[] not null default '{}', skills text[] not null default '{}', company_url text, certificate_path text, certificate_name text, certificate_type text, certificate_size bigint, experience_letter_path text, experience_letter_name text, experience_letter_type text, experience_letter_size bigint, notes text, tags text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.courses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, academic_year_id uuid references public.academic_years(id) on delete set null, semester_id uuid references public.semesters(id) on delete set null, course_name text not null, platform text, organization_instructor text, start_date date, completion_date date, duration text, skills_learned text[] not null default '{}', course_url text, certificate_path text, certificate_name text, certificate_type text, certificate_size bigint, status text not null default 'planned' check (status in ('planned','in_progress','completed')), notes text, tags text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.skills (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, normalized_name text not null, category text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, normalized_name));
create index if not exists internships_user_created_idx on public.internships(user_id,created_at desc); create index if not exists courses_user_created_idx on public.courses(user_id,created_at desc); create index if not exists skills_user_name_idx on public.skills(user_id,normalized_name);
create or replace function public.touch_phase6_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists internships_updated_at on public.internships; create trigger internships_updated_at before update on public.internships for each row execute function public.touch_phase6_updated_at();
drop trigger if exists courses_updated_at on public.courses; create trigger courses_updated_at before update on public.courses for each row execute function public.touch_phase6_updated_at();
drop trigger if exists skills_updated_at on public.skills; create trigger skills_updated_at before update on public.skills for each row execute function public.touch_phase6_updated_at();
alter table public.internships enable row level security;
alter table public.courses enable row level security;
alter table public.skills enable row level security;

drop policy if exists internships_select_own on public.internships; drop policy if exists internships_insert_own on public.internships; drop policy if exists internships_update_own on public.internships; drop policy if exists internships_delete_own on public.internships; create policy internships_select_own on public.internships for select using (auth.uid()=user_id); create policy internships_insert_own on public.internships for insert with check (auth.uid()=user_id); create policy internships_update_own on public.internships for update using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy internships_delete_own on public.internships for delete using (auth.uid()=user_id);
drop policy if exists courses_select_own on public.courses; drop policy if exists courses_insert_own on public.courses; drop policy if exists courses_update_own on public.courses; drop policy if exists courses_delete_own on public.courses; create policy courses_select_own on public.courses for select using (auth.uid()=user_id); create policy courses_insert_own on public.courses for insert with check (auth.uid()=user_id); create policy courses_update_own on public.courses for update using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy courses_delete_own on public.courses for delete using (auth.uid()=user_id);
drop policy if exists skills_select_own on public.skills; drop policy if exists skills_insert_own on public.skills; drop policy if exists skills_update_own on public.skills; drop policy if exists skills_delete_own on public.skills; create policy skills_select_own on public.skills for select using (auth.uid()=user_id); create policy skills_insert_own on public.skills for insert with check (auth.uid()=user_id); create policy skills_update_own on public.skills for update using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy skills_delete_own on public.skills for delete using (auth.uid()=user_id);
insert into storage.buckets(id,name,public) values ('portfolio-files','portfolio-files',false) on conflict(id) do nothing;
drop policy if exists portfolio_files_select_own on storage.objects; drop policy if exists portfolio_files_insert_own on storage.objects; drop policy if exists portfolio_files_update_own on storage.objects; drop policy if exists portfolio_files_delete_own on storage.objects; create policy portfolio_files_select_own on storage.objects for select using(bucket_id='portfolio-files' and auth.uid()::text=(storage.foldername(name))[1]); create policy portfolio_files_insert_own on storage.objects for insert with check(bucket_id='portfolio-files' and auth.uid()::text=(storage.foldername(name))[1]); create policy portfolio_files_update_own on storage.objects for update using(bucket_id='portfolio-files' and auth.uid()::text=(storage.foldername(name))[1]) with check(bucket_id='portfolio-files' and auth.uid()::text=(storage.foldername(name))[1]); create policy portfolio_files_delete_own on storage.objects for delete using(bucket_id='portfolio-files' and auth.uid()::text=(storage.foldername(name))[1]);
